stateDiagram-v2
state "Label" as A: entry / record
A --> B : event {text}

stateDiagram-v2
state Left {
a
}
state Right {
b
}
a --> b

stateDiagram-v2
state A {
state B {
state C {
[*] --> Ready
}
}
}

stateDiagram-v2
state Empty {
}
[*] --> Empty

stateDiagram-v2
state Group {
A
}
Group : First
Group : Second

stateDiagram-v2
state Active {
[*] --> A
A --> B
--
[*] --> C
state Nested {
[*] --> D
}
C --> Nested
}

stateDiagram-v2
state Left {
[*] --> Same
}
state Right {
[*] --> Same
}

stateDiagram-v2
    [*] --> First
    state First {
        [*] --> second
        second --> [*]
    }

    [*] --> NamedComposite
    NamedComposite: Another Composite
    state NamedComposite {
        [*] --> namedSimple
        namedSimple --> [*]
        namedSimple: Another simple
    }

stateDiagram-v2
    [*] --> First

    state First {
        [*] --> Second

        state Second {
            [*] --> second
            second --> Third

            state Third {
                [*] --> third
                third --> [*]
            }
        }
    }

stateDiagram-v2
    [*] --> First
    First --> Second
    First --> Third

    state First {
        [*] --> fir
        fir --> [*]
    }
    state Second {
        [*] --> sec
        sec --> [*]
    }
    state Third {
        [*] --> thi
        thi --> [*]
    }

